'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "name": "dataset"
  },
  "params": [
    { "name": "fAgent", "value": "Agent Name" },
    { "name": "fYear", "value": "year" },
    { "name": "fMonth", "value": "Month" },
    { "name": "fApe", "value": "APE" },
    { "name": "fMonthlyTarget", "value": "Monthly Target" },
    { "name": "fApeVsTarget", "value": "APE vs Target %" }
  ],
  "transform": [
    {
      "calculate": "datum[fAgent]",
      "as": "agent"
    },
    {
      "calculate": "datum[fYear]",
      "as": "yr"
    },
    {
      "calculate": "datum[fMonth]",
      "as": "month"
    },
    {
      "calculate": "isValid(datum[fApe]) && isFinite(toNumber(datum[fApe])) ? toNumber(datum[fApe]) : 0",
      "as": "ape"
    },
    {
      "calculate": "isValid(datum[fMonthlyTarget]) && isFinite(toNumber(datum[fMonthlyTarget])) ? toNumber(datum[fMonthlyTarget]) : 0",
      "as": "monthlyTarget"
    },
    {
      "calculate": "isValid(datum[fApeVsTarget]) && isFinite(toNumber(datum[fApeVsTarget])) ? toNumber(datum[fApeVsTarget]) : 0",
      "as": "apeVsTarget"
    },
    {
      "calculate": "toString(datum.yr) + ''-'' + toString(datum.month)",
      "as": "yearMonth"
    },
    {
      "calculate": "toNumber(datum.yr) * 100 + indexof([''Jan'',''Feb'',''Mar'',''Apr'',''May'',''Jun'',''Jul'',''Aug'',''Sep'',''Oct'',''Nov'',''Dec''], substring(toString(datum.month), 0, 3)) + 1",
      "as": "yearMonthSort"
    },
    {
      "calculate": "format(datum.ape, '',.0f'') + '' / '' + format(datum.apeVsTarget, ''.0%'')",
      "as": "cellLabel"
    }
  ],
  "width": {
    "step": 75
  },
  "height": {
    "step": 45
  },
  "encoding": {
    "x": {
      "field": "yearMonth",
      "type": "ordinal",
      "title": "Year - Month",
      "sort": {
        "field": "yearMonthSort",
        "op": "min",
        "order": "ascending"
      },
      "axis": {
        "orient": "top",
        "title": "Year - Month",
        "labels": true,
        "ticks": true,
        "domain": true,
        "labelAngle": -45,
        "labelFontSize": 10,
        "labelOverlap": false,
        "labelLimit": 120,
        "labelFlush": false
      }
    },
    "y": {
      "field": "agent",
      "type": "nominal",
      "title": "Agent",
      "sort": {
        "field": "ape",
        "op": "sum",
        "order": "descending"
      },
      "scale": {
        "paddingInner": 0.05,
        "paddingOuter": 0.02
      },
      "axis": {
        "orient": "left",
        "title": "Agent",
        "labels": true,
        "ticks": true,
        "domain": true,
        "labelFontSize": 10,
        "labelLimit": 150
      }
    }
  },
  "layer": [
    {
      "mark": {
        "type": "rect",
        "stroke": "white",
        "strokeWidth": 1
      },
      "encoding": {
        "color": {
          "condition": [
            {
              "test": "datum.apeVsTarget < 1",
              "value": "#E57373"
            },
            {
              "test": "datum.apeVsTarget > 1",
              "value": "#81C784"
            }
          ],
          "value": "#F5F5F5",
          "legend": null
        },
        "tooltip": [
          {
            "field": "agent",
            "type": "nominal",
            "title": "Agent"
          },
          {
            "field": "yr",
            "type": "ordinal",
            "title": "Year"
          },
          {
            "field": "month",
            "type": "nominal",
            "title": "Month"
          },
          {
            "field": "ape",
            "type": "quantitative",
            "title": "Total APE",
            "format": ",.0f"
          },
          {
            "field": "monthlyTarget",
            "type": "quantitative",
            "title": "Monthly Target",
            "format": ",.0f"
          },
          {
            "field": "apeVsTarget",
            "type": "quantitative",
            "title": "APE vs Target %",
            "format": ".1%"
          }
        ]
      }
    },
    {
      "mark": {
        "type": "text",
        "fontSize": 10,
        "color": "#000000",
        "align": "center",
        "baseline": "middle"
      },
      "encoding": {
        "text": {
          "field": "cellLabel",
          "type": "nominal"
        }
      }
    }
  ],
  "config": {
    "view": {
      "stroke": null
    },
    "axis": {
      "grid": false,
      "domain": true,
      "ticks": true,
      "labels": true
    }
  }
}'

